 document.getElementById('again').addEventListener('click',()=>{document.getElementById('card').classList.remove('open');points.length=0;trace.geometry.setFromPoints([]);coverage.fill(0);document.getElementById('bar').style.width='0';round++;document.getElementById('round').textContent='ROUND '+String(round).padStart(2,'0');setHint('Hold & trace the glowing circle')});

