 const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();ring.rotation.z=Math.sin(t*.18)*.025;particles.rotation.z=t*.012;orb.visible&&orb.scale.setScalar(.9+Math.sin(t*8)*.12);renderer.render(scene,camera)}animate();
